      "assessment": {
        "nobel_worthiness": "A decisive new quantum state of matter, joining a powerful topological theory to experimentally resolved edge transport.",
        "attribution": "Kane and Mele supplied the defining quantum-spin-Hall theory, while Molenkamp provided a landmark experimental realization.",
        "maturity": "The framework has been repeatedly confirmed and has reshaped condensed-matter physics for two decades.",
        "uncertainties": [
          "The appropriate boundary between the quantum spin Hall effect and the wider topological-insulator field requires careful framing."
        ]
      }
    },
