      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "DMFT made strongly correlated electrons quantitatively tractable and gave a durable bridge between microscopic models and measured spectra.",
        "attribution": "These three figures are central to the formulation, development, and establishment of dynamical mean-field theory.",
        "maturity": "Its predictions and computational extensions have been extensively tested across correlated materials.",
        "uncertainties": [
          "It is a theoretical method rather than a single experimentally discovered phenomenon.",
          "The broad collaborative development makes precise division of credit difficult."
        ]
      }
    },
